'use strict';
if(!platforms.includes('Webnovel'))platforms.push('Webnovel');
navs.webnovel='Webnovel';paths.webnovel=paths.series;navGroups.find(g=>g[0]==='Phân phối')[1].push('webnovel');
function findWebnovelChannel(){return db.channels.find(c=>c.platform==='Webnovel'||/webnovel/i.test(c.name||'')||/^https:\/\/(www\.)?webnovel\.com(?:\/|$)/i.test(c.link||''))}
const wnTemplates=[
{id:'wn_outline_v1',name:'Webnovel — Dàn ý bộ truyện',text:'Develop an original serial novel outline for {tên truyện}. Genre: {thể loại}. Premise: {ý tưởng}. Include the central conflict, character arcs, world rules, first 20 chapter beats and a longer-term arc. No copied characters, settings or text. This task is outlining, not writing chapter prose.'},
{id:'wn_chapter_v1',name:'Webnovel — Viết chương tiếp theo',text:'Write the next chapter of the original novel {tên truyện}. Chapter number: {số chương}. Follow the supplied outline, character profiles, world rules and established continuity. Scene goal: {mục tiêu chương}. Use the channel output language. Do not repeat earlier scenes or invent a contradiction. Target {số từ} words, with a purposeful chapter ending.'},
{id:'wn_review_v1',name:'Webnovel — Soát tính nhất quán',text:'Review this original chapter for continuity, pacing, dialogue and consistency with the story bible: {nội dung chương}. Report specific issues and suggested edits. Do not rewrite the entire chapter unless requested.'},
{id:'wn_blurb_v1',name:'Webnovel — Giới thiệu và teaser',text:'Create a compelling book synopsis and a short teaser for the original novel {tên truyện}. Genre: {thể loại}. Premise: {ý tưởng}. Follow the channel output language. Do not invent awards, popularity figures or reader quotes.'}
];
function prepareWebnovel(){if(loadError)return;db.setup??={};if(db.setup.webnovel42)return;const before=JSON.stringify(db);let c=findWebnovelChannel();if(!c){c={id:'channel_webnovel',name:'Webnovel',platform:'Webnovel',genre:'',link:'https://www.webnovel.com/',adminUrl:'https://inkstone.webnovel.com/',language:'English',audience:'Độc giả truyện dài kỳ quốc tế',style:'Rõ ràng, nhất quán nhân vật và diễn biến; chỉnh theo từng bộ truyện.',visual:'Bìa truyện theo nhân vật và bối cảnh gốc.',cadence:'',timeSlots:'',rules:'Truyện gốc; duyệt trước khi đăng. Không tự cam kết độc quyền hoặc doanh thu.',defaultPromptId:'wn_chapter_v1'};db.channels.push(c)}else if(!c.adminUrl)c.adminUrl='https://inkstone.webnovel.com/';for(const p of wnTemplates)if(!db.prompts.some(x=>x.id===p.id))db.prompts.push({...p});db.setup.webnovel42=true;if(!save())db=JSON.parse(before)}
prepareWebnovel();
const beforeWNRender=render;render=function(){if(view==='webnovel'){view='channels';beforeWNRender();view='webnovel';$('#main').innerHTML=webnovelPage();$('#breadcrumb').textContent='Không gian làm việc / Webnovel';document.title='Webnovel | Xưởng Nội Dung';horizontalNavigation()}else beforeWNRender();if($('#appVersion'))$('#appVersion').textContent='Xưởng 0.4.3'};
function webnovelPage(){const c=findWebnovelChannel();if(!c)return heading('Webnovel','Chuẩn bị kênh tác giả trước khi sản xuất truyện.')+`<section class="panel">${empty('Chưa có kênh Webnovel','Bạn có thể tạo lại cấu hình kênh.','<button id="wnSetup">Tạo kênh Webnovel</button>')}</section>`;const books=db.series.filter(s=>s.channelId===c.id);return heading('Webnovel','Sản xuất truyện trong Xưởng, duyệt rồi đăng thủ công lên Inkstone.',`<button data-edit="channels" data-id="${c.id}">Cấu hình kênh</button><button class="primary" id="wnNewBook">+ Tạo bộ truyện</button>`)+`<div class="notice"><div><strong>${esc(c.name)} / ngôn ngữ: ${esc(c.language||'English')}</strong><p>ChatGPT Bridge 0.4.0 dùng để viết. Chưa có kết nối đăng tự động hoặc đồng bộ tài khoản Webnovel.</p></div><button data-go="ai">Kết nối ChatGPT</button></div><section class="panel"><h2>Quy trình sản xuất</h2><p class="help-text mt">Hồ sơ truyện → dàn ý → chương → ChatGPT → duyệt → Inkstone.</p><div class="actions">${safeLink('https://www.webnovel.com/','Mở trang độc giả')}${safeLink(c.adminUrl||'https://inkstone.webnovel.com/','Mở Inkstone tác giả')}<button data-edit="prompts" data-id="wn_chapter_v1">Mẫu viết chương</button></div><p class="help-text mt">Không lưu thông tin ngân hàng. Việc xuất bản và hợp đồng thực hiện trên Inkstone. Bạn có thể đổi ngôn ngữ trong Cấu hình kênh.</p></section><div class="cards mt">${books.map(s=>{const chapters=db.content.filter(x=>x.seriesId===s.id&&x.productionTask!=='outline').sort((a,b)=>Number(a.chapterNumber||0)-Number(b.chapterNumber||0));return `<article class="panel"><span class="badge">${esc(s.exclusivity||'Không độc quyền')}</span><h2 class="mt">${esc(s.title)}</h2><p>${esc((s.synopsis||s.outline||'Chưa có giới thiệu hoặc dàn ý').slice(0,180))}</p><small>${chapters.length} chương / ${chapters.filter(c=>c.status==='live').length} đã đăng</small><div class="actions"><button data-edit="series" data-id="${s.id}">Hồ sơ truyện</button><button data-wn-outline="${s.id}">Soạn dàn ý bằng ChatGPT</button><button class="primary" data-wn-chapter="${s.id}">Viết chương tiếp theo</button></div>${db.content.filter(x=>x.seriesId===s.id&&x.productionTask==='outline').map(x=>`<div class="row"><span>${esc(x.title)} / ${statuses[x.status]}</span><div class="actions"><button data-edit="content" data-id="${x.id}">Mở</button>${x.status==='approved'?`<button data-wn-apply="${x.id}">Dùng làm dàn ý</button>`:''}</div></div>`).join('')}${chapters.map(x=>`<div class="row"><div><strong>${esc(x.title)}</strong><small>${statuses[x.status]}</small></div><button data-edit="content" data-id="${x.id}">Mở chương</button></div>`).join('')}</article>`}).join('')}</div>${books.length?'':`<section class="panel mt">${empty('Chưa có bộ truyện','Nhập tên truyện, ý tưởng, nhân vật và bối cảnh trước; Xưởng chưa tự tạo nội dung khi bạn chưa gửi yêu cầu.','<button class="primary" id="wnNewBookEmpty">Tạo bộ truyện đầu tiên</button>')}</section>`}`}
const wnFullPrompt=fullPrompt;fullPrompt=function(){const d=formValue(),c=ch(d.channelId),s=db.series.find(x=>x.id===d.seriesId);let text=wnFullPrompt();if(c?.id===findWebnovelChannel()?.id){text+='\n\nNgôn ngữ đầu ra: '+(c.language||'English')+'. Bạn viết cho độc giả Webnovel. Đây là bản nháp cần người dùng duyệt, không tự đăng.';if(d.productionTask==='outline')text+='\nNhiệm vụ hiện tại là xây dựng DÀN Ý, không viết văn xuôi chương. Chỉ dùng hồ sơ bộ truyện, bỏ qua chương trước nếu không liên quan.';else{const current=Number(d.chapterNumber||0);const prior=db.content.filter(x=>x.seriesId===s?.id&&x.productionTask!=='outline'&&x.id!==editId&&(!current||Number(x.chapterNumber||0)<current)).sort((a,b)=>Number(a.chapterNumber||0)-Number(b.chapterNumber||0)).at(-1);if(prior?.summary)text+='\nTóm tắt chương liền trước: '+prior.summary}}return text};
const wnEditor=openEditor;openEditor=function(type,id='',defaults={}){wnEditor(type,id,defaults);if(type==='content'&&$('#editor').open&&editType==='content'){const o={...db.content.find(x=>x.id===id),...defaults};$('#fields').insertAdjacentHTML('beforeend',`<input type="hidden" name="productionTask" value="${esc(o.productionTask||'chapter')}">`)}if(type==='channels'&&$('#editor').open&&editType==='channels'){const o={...db.channels.find(x=>x.id===id),...defaults};$('#fields').insertAdjacentHTML('beforeend',input('adminUrl','Link quản trị tác giả',o.adminUrl||'','url'))}};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const channel=findWebnovelChannel();if(b.id==='wnSetup'){db.setup??={};delete db.setup.webnovel42;prepareWebnovel();render()}if(['wnNewBook','wnNewBookEmpty'].includes(b.id)&&channel)openEditor('series','',{channelId:channel.id,title:'',chapterLength:1500,exclusivity:'Không độc quyền'});if(b.dataset.wnOutline){const s=db.series.find(s=>s.id===b.dataset.wnOutline);if(s)openEditor('content','',{title:'Dàn ý — '+s.title,channelId:s.channelId,seriesId:s.id,status:'draft',kind:'Bài viết',productionTask:'outline',prompt:'Xây dựng dàn ý truyện gốc dựa trên hồ sơ này. Giới thiệu: '+(s.synopsis||'')+'\nÝ tưởng: '+s.outline+'\nNhân vật: '+s.characters+'\nBối cảnh: '+(s.world||'')+'\nTrình bày xung đột chính, tuyến phát triển nhân vật, các arc và 20 chương đầu. Không viết nội dung chương.'})}if(b.dataset.wnChapter){const s=db.series.find(s=>s.id===b.dataset.wnChapter);if(!s)return;if(!s.outline?.trim())return toast('Mở hồ sơ truyện và lưu dàn ý trước khi viết chương.');const n=Math.max(0,...db.content.filter(x=>x.seriesId===s.id&&x.productionTask!=='outline').map(x=>Number(x.chapterNumber)||0))+1;openEditor('content','',{title:'Chapter '+n+' — '+s.title,channelId:s.channelId,seriesId:s.id,status:'draft',kind:'Chương truyện',chapterNumber:n,productionTask:'chapter',prompt:'Viết chương '+n+' theo dàn ý, hồ sơ nhân vật và diễn biến đã xác lập. Độ dài mục tiêu '+(s.chapterLength||1500)+' từ. Không lặp lại chương trước. Giữ mạch truyện và kết chương có mục đích.'})}if(b.dataset.wnApply){const c=db.content.find(c=>c.id===b.dataset.wnApply),s=db.series.find(s=>s.id===c?.seriesId);if(!c||!s||c.status!=='approved')return;if(!await uiConfirm('Dùng nội dung đã duyệt này làm dàn ý bộ truyện? Dàn ý cũ được giữ trong lịch sử hồ sơ.'))return;const before=JSON.stringify(db);s.outlineHistory=[...(s.outlineHistory||[]),{at:new Date().toISOString(),outline:s.outline}].slice(-10);s.outline=c.body;if(!save()){db=JSON.parse(before);return}render();toast('Đã cập nhật dàn ý cho bộ truyện.')}});
view=navs[location.hash.slice(1)]?location.hash.slice(1):view;render();
